const mondayRaw = $('Pull Monday.com Tasks').first().json;
const ghlRaw = $('Pull GHL Pipeline Data').first().json;
const pandaRaw = $('Pull PandaDoc Proposals').first().json;
const config = $('Workflow Configuration').first().json;

const today = $now.toFormat('yyyy-MM-dd');
const nowMs = Date.now();

// Monday.com: task counts by status
const statusColId = config.mondayTaskStatusColumnId || 'status';
const dateColId = config.mondayTaskDateColumnId || 'date4';
const boardData = mondayRaw.data && mondayRaw.data.boards && mondayRaw.data.boards[0];
const allItems = boardData && boardData.items_page ? boardData.items_page.items : [];

let totalTasks = allItems.length;
let completedTasks = 0;
let overdueCount = 0;
let inProgressTasks = 0;
let notStartedTasks = 0;

allItems.forEach(function (item) {
  const cols = item.column_values || [];
  const statusCol = cols.find(function (c) { return c.id === statusColId; });
  const dateCol = cols.find(function (c) { return c.id === dateColId; });
  const status = statusCol && statusCol.text ? statusCol.text.toLowerCase() : '';
  const dueDate = dateCol && dateCol.text ? dateCol.text : '';
  const isDone = status.includes('done') || status.includes('complete');

  if (isDone) completedTasks++;
  else if (status.includes('progress') || status.includes('working')) inProgressTasks++;
  else notStartedTasks++;

  // Exclude today: strictly less-than, not less-than-or-equal
  if (dueDate && !isDone && dueDate.slice(0, 10) < today) overdueCount++;
});

const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

// GoHighLevel: lead counts and estimated pipeline value
// customFields can be an array [{id, fieldKey, value}] or a plain object
function getBudgetText(contact) {
  const cf = contact.customFields;
  if (Array.isArray(cf)) {
    const hit = cf.find(function (f) {
      const key = String(f.fieldKey || f.key || f.name || '').toLowerCase();
      return (config.ghlBudgetFieldId && f.id === config.ghlBudgetFieldId) || key.indexOf('budget') !== -1;
    });
    return hit && hit.value ? String(hit.value) : '';
  }
  return cf && cf.budget ? String(cf.budget) : '';
}

const contacts = ghlRaw.contacts || [];
let totalLeads = contacts.length;
let hotLeads = 0;
let warmLeads = 0;
let newLeadsToday = 0;
let estimatedPipelineValue = 0;

contacts.forEach(function (contact) {
  const tags = Array.isArray(contact.tags) ? contact.tags : [];
  if (tags.includes('lead-score-hot')) hotLeads++;
  if (tags.includes('lead-score-warm')) warmLeads++;

  const addedMs = new Date(contact.dateAdded || contact.date_added || 0).getTime();
  if ((nowMs - addedMs) / 3600000 <= 24) newLeadsToday++;

  // Fixed regex: /[\d,]+/ matches digits and commas (not letter 'd')
  const match = getBudgetText(contact).match(/[\d,]+/);
  if (match) {
    const val = parseInt(match[0].replace(/,/g, ''), 10);
    if (!isNaN(val)) estimatedPipelineValue += val;
  }
});

// PandaDoc: proposal status breakdown
const documents = pandaRaw.results || pandaRaw.documents || [];
let proposalsSent = 0;
let proposalsSigned = 0;
let proposalsPending = 0;
let proposalsDeclined = 0;
let proposalsNewToday = 0;

documents.forEach(function (doc) {
  const status = (doc.status || '').toLowerCase();
  const createdMs = new Date(doc.date_created || 0).getTime();

  if (status === 'document.sent' || status === 'sent') proposalsSent++;
  if (status === 'document.completed' || status === 'completed') proposalsSigned++;
  if (status === 'document.draft' || status === 'draft' || status === 'document.waiting_approval') proposalsPending++;
  if (status === 'document.voided' || status === 'document.declined') proposalsDeclined++;
  if ((nowMs - createdMs) / 3600000 <= 24) proposalsNewToday++;
});

// Anomaly flags
const overdueAlert = overdueCount >= (Number(config.overdueThreshold) || 5);
const pipelineLow = estimatedPipelineValue > 0 && estimatedPipelineValue < (Number(config.pipelineMinValue) || 0);
const noNewLeads = newLeadsToday === 0;

return [{
  json: {
    report_date: today,
    generated_at: new Date().toISOString(),
    monday: { total_tasks: totalTasks, completed: completedTasks, in_progress: inProgressTasks, not_started: notStartedTasks, overdue: overdueCount, completion_rate: completionRate },
    ghl: { total_leads: totalLeads, hot_leads: hotLeads, warm_leads: warmLeads, new_today: newLeadsToday, estimated_pipeline_value: estimatedPipelineValue },
    pandadoc: { sent: proposalsSent, signed: proposalsSigned, pending: proposalsPending, declined: proposalsDeclined, new_today: proposalsNewToday },
    anomalies: { overdue_alert: overdueAlert, pipeline_low: pipelineLow, no_new_leads: noNewLeads },
    config: config
  }
}];

