const aiSummary = $('Synthesize Executive Summary with Gemini').first().json.output || 'Summary unavailable.';
const data = $('Aggregate All Data').first().json;
const cfg = data.config;
const company = cfg.companyName || 'Management';
const threshold = Number(cfg.overdueThreshold) || 5;

const d = data.monday;
const g = data.ghl;
const p = data.pandadoc;
const date = data.report_date;

// HTML-escape helper — used in email to prevent injection
function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const safeSummary = esc(aiSummary);
const pipelineK = (g.estimated_pipeline_value / 1000).toFixed(0);

const taskStatus = data.anomalies.overdue_alert ? '🔴' : d.completion_rate >= 70 ? '🟢' : '🟡';
const salesStatus = data.anomalies.no_new_leads ? '🔴' : g.hot_leads > 0 ? '🟢' : '🟡';
const proposalStatus = p.declined > p.signed ? '🔴' : p.signed >= p.sent ? '🟢' : '🟡';

// Slack message — backticks via variable to avoid parser issues
var codeBlock = '```';
var slackMsg = [
  '*📊 ' + company + ' Management Briefing: ' + date + '*',
  '',
  '*Operations* ' + taskStatus + '  |  *Sales* ' + salesStatus + '  |  *Proposals* ' + proposalStatus,
  '',
  codeBlock,
  'TASKS            PIPELINE            PROPOSALS',
  'Total:    ' + String(d.total_tasks).padEnd(5) + '   Hot Leads:  ' + String(g.hot_leads).padEnd(5) + '   Signed:  ' + p.signed,
  'Done:     ' + String(d.completed).padEnd(5) + '   Warm:       ' + String(g.warm_leads).padEnd(5) + '   Sent:    ' + p.sent,
  'Overdue:  ' + String(d.overdue).padEnd(5) + '   New Today:  ' + String(g.new_today).padEnd(5) + '   Pending: ' + p.pending,
  'Rate:     ' + d.completion_rate + '%' + '     Pipeline:   $' + pipelineK + 'K',
  codeBlock,
  '',
  '*AI Executive Summary:*',
  aiSummary,
  '',
  '_Automated by n8n_'
].join('\n');

// HTML email
const overdueClass = d.overdue >= threshold ? 'red' : d.overdue > 0 ? 'yellow' : 'green';
const overdueLabel = d.overdue >= threshold ? '⚠ Critical' : d.overdue > 0 ? '! Needs attention' : '✓ None';

const htmlEmail = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>
body { font-family: Arial, sans-serif; font-size: 14px; color: #333; max-width: 700px; margin: 0 auto; padding: 24px; }
h1 { color: #1a1a2e; font-size: 20px; border-bottom: 2px solid #0066cc; padding-bottom: 8px; }
h2 { font-size: 15px; color: #0066cc; margin-top: 24px; }
table { width: 100%; border-collapse: collapse; margin: 12px 0; }
th { background: #f0f4ff; text-align: left; padding: 8px 12px; font-size: 12px; text-transform: uppercase; }
td { padding: 8px 12px; border-bottom: 1px solid #eee; }
.green { color: #16a34a; font-weight: bold; }
.yellow { color: #ca8a04; font-weight: bold; }
.red { color: #dc2626; font-weight: bold; }
.status-bar { background: #f8f9fa; border-radius: 8px; padding: 12px 16px; margin: 16px 0; font-size: 16px; }
.summary-box { background: #f0f7ff; border-left: 4px solid #0066cc; padding: 16px; border-radius: 4px; white-space: pre-wrap; line-height: 1.7; }
.footer { margin-top: 32px; font-size: 12px; color: #999; border-top: 1px solid #eee; padding-top: 12px; }
</style></head>
<body>
<h1>📊 ${esc(company)} Management Briefing: ${date}</h1>
<div class="status-bar">Operations ${taskStatus}    Sales ${salesStatus}    Proposals ${proposalStatus}</div>
<h2>Task Accountability (Monday.com)</h2>
<table>
<tr><th>Metric</th><th>Count</th><th>Status</th></tr>
<tr><td>Total Tasks</td><td>${d.total_tasks}</td><td></td></tr>
<tr><td>Completed</td><td>${d.completed} (${d.completion_rate}%)</td><td class="green">✓ Done</td></tr>
<tr><td>In Progress</td><td>${d.in_progress}</td><td class="yellow">⟳ Active</td></tr>
<tr><td>Not Started</td><td>${d.not_started}</td><td></td></tr>
<tr><td>Overdue</td><td>${d.overdue}</td><td class="${overdueClass}">${overdueLabel}</td></tr>
</table>
<h2>Sales Pipeline (GoHighLevel)</h2>
<table>
<tr><th>Metric</th><th>Count</th></tr>
<tr><td>Total Leads</td><td>${g.total_leads}</td></tr>
<tr><td>Hot Leads (score 8-10)</td><td class="${g.hot_leads > 0 ? 'red' : ''}">${g.hot_leads}${g.hot_leads > 0 ? ' - immediate action needed' : ''}</td></tr>
<tr><td>Warm Leads (score 5-7)</td><td>${g.warm_leads} - in nurture sequence</td></tr>
<tr><td>New Leads (last 24h)</td><td class="${g.new_today === 0 ? 'red' : 'green'}">${g.new_today}</td></tr>
<tr><td>Est. Pipeline Value</td><td>USD ${g.estimated_pipeline_value.toLocaleString('en-US')}</td></tr>
</table>
<h2>Proposals (PandaDoc)</h2>
<table>
<tr><th>Status</th><th>Count</th></tr>
<tr><td>Signed / Completed</td><td class="green">${p.signed}</td></tr>
<tr><td>Sent (awaiting)</td><td>${p.sent}</td></tr>
<tr><td>Draft / Pending</td><td>${p.pending}</td></tr>
<tr><td>Declined / Voided</td><td class="${p.declined > 0 ? 'red' : ''}">${p.declined}</td></tr>
<tr><td>New Today</td><td>${p.new_today}</td></tr>
</table>
<h2>AI Executive Summary</h2>
<div class="summary-box">${safeSummary}</div>
<div class="footer">Automated by n8n · ${esc(company)} internal report · ${date}<br>Sources: Monday.com · GoHighLevel · PandaDoc</div>
</body>
</html>`;

const mondayItemName = 'Daily Report ' + date + ' | Tasks: ' + d.completion_rate + '% | Hot Leads: ' + g.hot_leads + ' | Signed: ' + p.signed;

return [{
  json: {
    slack_message: slackMsg,
    email_subject: company + ' Daily Briefing ' + date + ' | ' + taskStatus + ' Ops · ' + salesStatus + ' Sales · ' + proposalStatus + ' Proposals',
    email_html: htmlEmail,
    monday_item_name: mondayItemName,
    monday_notes: 'Overdue: ' + d.overdue + ' | Hot leads: ' + g.hot_leads + ' | Signed proposals: ' + p.signed + ' | Pipeline: $' + pipelineK + 'K',
    config: cfg
  }
}];
